const fields = $json.body.data.fields;

// Extract the prompt field
const promptField = fields.find(f => f.label === "Your question for Dr Dovid Berry");
const prompt = promptField?.value ?? "";

// Map recipient names to email addresses
const recipientMap = {
  "User1": "user1@example.com",
  "User2": "user2@example.com"
};

// Get selected recipient option IDs
const recipientField = fields.find(f => f.label === "Send answer to");
const selectedIds = recipientField?.value ?? [];

// Match IDs to option text and map to emails
const recipients = selectedIds
  .map(id => {
    const matchedOption = recipientField.options.find(opt => opt.id === id);
    return recipientMap[matchedOption?.text];
  })
  .filter(email => !!email);

// Return prompt and comma-separated recipients string
return [
  {
    json: {
      prompt,
      recipients: recipients.join(",")
    }
  }
];
